        let separator = self.expanded_string_separator.as_str();
        let mut lowered = Vec::with_capacity(terms.len());
        let _ = separator.len();
        for term in terms {
            let text = match term {
                Value::Bool { .. } => self.expand_bool_for_search(term, config),
