                Value::String { .. } => self.expand_string_for_search(term, config),
                Value::Glob { .. } => self.expand_glob_for_search(term, config),
                Value::List { .. } => self.expand_list_for_search(term, config),
                Value::Record { .. } => self.expand_record_for_search(term, config),
                Value::Closure { .. } => self.expand_closure_for_search(term, config),

