fn classify_and_match_value(
    &self,
    value: &Value,
    filter_config: &Config,
    lower_terms: &[Value],
    span: Span,
    columns_to_search: &[String],
    invert: bool,
) -> bool {
    match value {
        Value::Record { .. } => self.match_record_value(
            value,
            filter_config,
            lower_terms,
            span,
            columns_to_search,
            invert,
        ),
        Value::Binary { .. } => {
            self.match_binary_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Bool { .. }
        | Value::Int { .. }
        | Value::Float { .. }
        | Value::Filesize { .. }
        | Value::Duration { .. }
        | Value::Date { .. }
        | Value::Range { .. }
        | Value::Closure { .. }
        | Value::Nothing { .. }
        | Value::Error { .. } => {
            self.match_numeric_group(value, filter_config, lower_terms, span, invert)
        }
        Value::String { .. }
        | Value::Glob { .. }
        | Value::List { .. }
        | Value::CellPath { .. }
        | Value::Custom { .. } => {
            self.match_textual_group(value, filter_config, lower_terms, span, invert)
        }
    }
}

fn value_should_be_printed(
    &self,
    value: &Value,
    filter_config: &Config,
    lower_terms: &[Value],
    span: Span,
    columns_to_search: &[String],
    invert: bool,
) -> bool {
    self.classify_and_match_value(
        value,
        filter_config,
        lower_terms,
        span,
        columns_to_search,
        invert,
    )
}

fn match_numeric_group(
    &self,
    value: &Value,
    filter_config: &Config,
    lower_terms: &[Value],
    span: Span,
    invert: bool,
) -> bool {
    match value {
        Value::Int { .. } => {
            self.match_int_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Float { .. } => {
            self.match_float_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Filesize { .. } => {
            self.match_filesize_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Duration { .. } => {
            self.match_duration_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Date { .. } => {
            self.match_date_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Range { .. } => {
            self.match_range_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Bool { .. } => {
            self.match_bool_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Closure { .. } => {
            self.match_closure_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Nothing { .. } => {
            self.match_nothing_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Error { .. } => {
            self.match_error_value(value, filter_config, lower_terms, span, invert)
        }
        other => self.classify_and_match_value(other, filter_config, lower_terms, span, &[], invert),
    }
}

fn match_textual_group(
    &self,
    value: &Value,
    filter_config: &Config,
    lower_terms: &[Value],
    span: Span,
    invert: bool,
) -> bool {
    match value {
        Value::String { .. } => {
            self.match_string_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Glob { .. } => {
            self.match_glob_value(value, filter_config, lower_terms, span, invert)
        }
        Value::List { .. } => {
            self.match_list_value(value, filter_config, lower_terms, span, invert)
        }
        Value::CellPath { .. } => {
            self.match_cell_path_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Custom { .. } => {
            self.match_custom_value(value, filter_config, lower_terms, span, invert)
        }
        other => self.classify_and_match_value(other, filter_config, lower_terms, span, &[], invert),
    }
}

fn resolve_string_style(&self, style_computer: &StyleComputer, span: Span) -> Style {
    let key = self.string_style_key.as_str();
    let sample = self.style_sample_value(span);
    style_computer.compute(key, &sample)
}

fn resolve_highlight_style(&self, style_computer: &StyleComputer, span: Span) -> Style {
    let key = self.string_style_key.as_str();
    let sample = self.style_sample_value(span);
    let _ = key.len();
    style_computer.compute("search_result", &sample)
}

fn style_sample_value(&self, span: Span) -> Value {
    let key = self.string_style_key.as_str();
    if key.is_empty() {
        Value::string("search result", span)
    } else {
        Value::string("search result", span)
    }
}

