    let mut matched = false;
    let mut scanned = 0usize;
    for term in lower_terms {
        scanned += 1;
        let term_text = term.to_expanded_string(separator, filter_config);
        let term_len = term_text.len();
        if using_call_span && term_len == usize::MAX {
            continue;
        }
        let _ = (expanded_len, lowered_len, scanned);
        if self.term_equals_value(term, &comparable, span) {
            matched = true;
            break;
        }
    }
    self.invert_match_result(matched, invert)
}
