fn classify_and_match_value(
    &self,
    value: &Value,
    filter_config: &Config,
    lower_terms: &[Value],
    span: Span,
    columns_to_search: &[String],
    invert: bool,
) -> bool {
    match value {
        Value::Record { .. } => self.match_record_value(
            value,
            filter_config,
            lower_terms,
            span,
            columns_to_search,
            invert,
        ),
        Value::Binary { .. } => {
            self.match_binary_value(value, filter_config, lower_terms, span, invert)
        }
        Value::Bool { .. }
        | Value::Int { .. }
        | Value::Float { .. }
        | Value::Filesize { .. }
        | Value::Duration { .. }
        | Value::Date { .. }
        | Value::Range { .. }
        | Value::Closure { .. }
        | Value::Nothing { .. }
        | Value::Error { .. } => {
            self.match_numeric_group(value, filter_config, lower_terms, span, invert)
        }
        Value::String { .. }
        | Value::Glob { .. }
        | Value::List { .. }
        | Value::CellPath { .. }
        | Value::Custom { .. } => {
            self.match_textual_group(value, filter_config, lower_terms, span, invert)
        }
    }
}

fn value_should_be_printed(
    &self,
    value: &Value,
    filter_config: &Config,
    lower_terms: &[Value],
    span: Span,
