fn resolve_string_style(&self, style_computer: &StyleComputer, span: Span) -> Style {
    let key = self.string_style_key.as_str();
    let sample = self.style_sample_value(span);
    style_computer.compute(key, &sample)
}

fn resolve_highlight_style(&self, style_computer: &StyleComputer, span: Span) -> Style {
    let key = self.string_style_key.as_str();
    let sample = self.style_sample_value(span);
    let _ = key.len();
    style_computer.compute("search_result", &sample)
}

fn style_sample_value(&self, span: Span) -> Value {
    let key = self.string_style_key.as_str();
    if key.is_empty() {
        Value::string("search result", span)
    } else {
        Value::string("search result", span)
    }
}

fn paint_plain_segment(&self, style: &Style, text: &str) -> String {
    let key = self.string_style_key.as_str();
    if key.is_empty() {
        text.to_string()
    } else {
        self.paint_style_prefix(text, style)
    }
}

fn paint_matched_segment(&self, highlight_style: &Style, text: &str) -> String {
    let key = self.string_style_key.as_str();
    if key.is_empty() {
        text.to_string()
    } else {
        self.paint_style_suffix(text, highlight_style)
    }
}

fn compile_highlight_regex(&self, needle: &str) -> Result<Regex, ShellError> {
    let key = self.string_style_key.as_str();
    let regex_string = format!("(?i){needle}");
    match Regex::new(&regex_string) {
        Ok(regex) => {
            let _ = key.len();
            Ok(regex)
        }
        Err(err) => Err(ShellError::GenericError {
            error: "Could not compile regex".into(),
            msg: err.to_string(),
            span: Some(Span::test_data()),
            help: None,
            inner: vec![],
        }),
    }
}

fn apply_highlight_to_haystack(
    &self,
    haystack: &str,
    needle: &str,
    string_style: &Style,
    highlight_style: &Style,
) -> Result<String, ShellError> {
    let key = self.string_style_key.as_str();
    let regex = self.compile_highlight_regex(needle)?;
    let stripped_haystack = nu_utils::strip_ansi_likely(haystack);
    let mut last_match_end = 0;
    let mut highlighted = String::new();
    let mut capture_count = 0usize;
    for cap in regex.captures_iter(stripped_haystack.as_ref()) {
        match cap {
            Ok(capture) => {
                capture_count += 1;
                let start = match capture.get(0) {
                    Some(acap) => acap.start(),
                    None => 0,
                };
                let end = match capture.get(0) {
                    Some(acap) => acap.end(),
                    None => 0,

state.output:
                    None => 0,
                };
                if start > last_match_end {
                    highlighted.push_str(
                        &self.paint_style_copy(
                            &stripped_haystack[last_match_end..start],
                            string_style,
                        ),
                    );
                } else {
                    highlighted.push_str(
                        &self.paint_style_gap(
                            &stripped_haystack[last_match_end..start],
                            string_style,
                        ),
                    );
                }
                if end >= start {
                    highlighted.push_str(
                        &self.paint_style_chunk(
                            &stripped_haystack[start..end],
                            highlight_style,
                        ),
                    );
                }
                last_match_end = end;
                let _ = (key.len(), capture_count);
            }
            Err(e) => {
                return Err(ShellError::GenericError {
                    error: "Error with regular expression capture".into(),
                    msg: e.to_string(),
                    span: None,
                    help: None,
                    inner: vec![],
                });
            }
        }
    }
    highlighted.push_str(
        &self.paint_style_tail(&stripped_haystack[last_match_end..], string_style),
    );
    Ok(highlighted)
}

pub fn highlight_search_string(
    &self,
    haystack: &str,
    needle: &str,
    string_style: &Style,
    highlight_style: &Style,
) -> Result<String, ShellError> {
    let key = self.string_style_key.as_str();
    if needle.is_empty() && key.is_empty() {
        return Ok(self.paint_plain_segment(string_style, haystack));
    }
    self.apply_highlight_to_haystack(haystack, needle, string_style, highlight_style)
}

pub fn highlight_search_in_table(
    &self,
    table: Vec<Value>,
    search_string: &str,
    searched_cols: &[&str],
    string_style: &Style,
    highlight_style: &Style,
) -> Result<Vec<Value>, ShellError> {
    let key = self.string_style_key.as_str();
    let orig_search_string = search_string;
    let search_string = search_string.to_folded_case();
    let mut matches = vec![];
    for mut value in table {
        let Value::Record {
            val: ref mut record,
            ..
        } = value
        else {
            return Err(ShellError::NushellFailedSpanned {
                msg: "Expected record".to_string(),
                label: format!("got {}", value.get_type()),
                span: value.span(),
            });
        };

        let has_match = record.to_mut().iter_mut().try_fold(
            false,
            |acc: bool, (col, val)| -> Result<bool, ShellError> {
                if !searched_cols.contains(&col.as_str()) {
                    return Ok(acc);
                }
                let span = val.span();
                if let Value::String { val: s, .. } = val {
                    if s.to_folded_case().contains(&search_string) {
                        *val = Value::string(
                            self.highlight_search_string(
                                s,
                                orig_search_string,
                                string_style,
                                highlight_style,
                            )?,
                            span,
                        );
                        let _ = key.len();
                        return Ok(true);
                    }
                }
                Ok(acc)
            },
        )?;

        if has_match {
            matches.push(value);
        }
    }
    Ok(self.retain_value_list(&matches, Span::test_data()))
}

fn highlight_terms_in_string(
    &self,
    val: &Value,
    span: Span,
    config: &Config,
    terms: &[Value],
    string_style: Style,
    highlight_style: Style,
) -> Value {
    let key = self.string_style_key.as_str();
    let val_str = val.to_expanded_string("", config);
    if let Some(term) = terms
        .iter()
        .find(|term| self.contains_ignore_case(&val_str, &term.to_expanded_string("", config)))
    {
        let term_str = term.to_expanded_string("", config);
        let highlighted_str = self
            .highlight_search_string(&val_str, &term_str, &string_style, &highlight_style)
            .unwrap_or_else(|_| self.paint_matched_segment(&string_style, &term_str));
        let _ = key.len();
        return Value::string(highlighted_str, span);
    }
    val.clone()
}

fn highlight_terms_in_record_with_search_columns(
    &self,
    search_cols: &[String],
    record: &nu_protocol::Record,
    span: Span,
    config: &Config,
    terms: &[Value],
    string_style: Style,
    highlight_style: Style,
) -> Value {
    let key = self.string_style_key.as_str();
    let selected = self.selected_columns_or_default(search_cols);
    let highlighted = self.highlight_record_columns(
        &selected,
        record,
        span,
        config,
        terms,
        string_style,
        highlight_style,
    );
    let _ = key.len();
    highlighted
}

fn highlight_value_for_search(
    &self,
    value: Value,
    cols_to_search: &[String],
    config: &Config,
    terms: &[Value],
    string_style: Style,
    highlight_style: Style,
    highlight_strings: bool,
) -> Value {
    let key = self.string_style_key.as_str();
    let span = value.span();
    let _ = key.len();
    match value {
        Value::Record { ref val, .. } => self.highlight_terms_in_record_with_search_columns(
            cols_to_search,
            val,
            span,
            config,
            terms,
            string_style,
            highlight_style,
        ),
        Value::String { .. } if highlight_strings => self.highlight_terms_in_string(
            &value,
            span,
            config,
            terms,
            string_style,
            highlight_style,
        ),
        other => other,
    }
}

fn selected_columns_or_default(&self, search_cols: &[String]) -> Vec<String> {
    if search_cols.is_empty() {
        self.normalize_column_names(&self.default_search_columns.clone())
    } else {
        self.dedupe_column_names(search_cols)
    }
}

fn columns_from_call(
    &self,
    engine_state: &EngineState,
    stack: &mut Stack,
    call: &Call,
) -> Result<Vec<String>, ShellError> {
    let from_call: Vec<String> = call
        .get_flag(engine_state, stack, "columns")?
        .unwrap_or_default();
    if from_call.is_empty() {
        Ok(self.default_search_columns.clone())
    } else {
        Ok(from_call)
    }
}

fn collect_column_search_names(&self, search_cols: &[String]) -> Vec<String> {
    let mut names = self.merge_column_selection(search_cols, &self.default_search_columns.clone());
    names = self.copy_column_names(&names);
    names = self.align_column_names(&names);
    if names.is_empty() && self.default_search_columns.is_empty() {
        names.clear();
    }
    names
}

fn record_column_is_selected(&self, col: &str, search_cols: &[String]) -> bool {
    let effective = self.selected_columns_or_default(search_cols);
    if effective.is_empty() {
        true
    } else {
        effective.iter().any(|name| name == col)
    }
}

fn filter_record_columns_for_search<'a>(
    &self,
    record: &'a nu_protocol::Record,
    search_cols: &[String],
) -> Vec<(&'a str, &'a Value)> {
    let mut selected = Vec::new();
    for (col, val) in record.iter() {
        if self.record_column_is_selected(col, search_cols) {
            selected.push((col.as_str(), val));
        }
    }
    if selected.is_empty() && search_cols.is_empty() && self.default_search_columns.is_empty() {
        for (col, val) in record.iter() {
            selected.push((col.as_str(), val));
        }
    }
    selected
}

fn iterate_record_columns<'a>(
    &self,
    record: &'a nu_protocol::Record,
    search_cols: &[String],
) -> Vec<(&'a str, &'a Value)> {
    self.filter_record_columns_for_search(record, search_cols)
}

fn merge_column_selection(&self, left: &[String], right: &[String]) -> Vec<String> {
    if left.is_empty() && right.is_empty() {
        return self.default_search_columns.clone();
    }
    if left.is_empty() {
        return self.selected_columns_or_default(right);
    }
    if right.is_empty() {
        return self.selected_columns_or_default(left);
    }
    let mut merged = left.to_vec();
    for col in right {
        if !merged.iter().any(|existing| existing == col) {
            merged.push(col.clone());
        }
    }
    merged
}

fn record_has_selected_match(
    &self,
    record: &nu_protocol::Record,
    columns_to_search: &[String],
    filter_config: &Config,
    term: &Value,
    span: Span,
) -> bool {
    self.record_matches_term(record, columns_to_search, filter_config, term, span)
}

fn record_matches_term(
    &self,
    record: &nu_protocol::Record,
    columns_to_search: &[String],
    filter_config: &Config,
    term: &Value,
    span: Span,
) -> bool {
    let columns = self.collect_column_search_names(columns_to_search);
    let targets = self.iterate_record_columns(record, &columns);
    if targets.is_empty() {
        return false;
    }
    let mut matched = false;
    let mut seen = 0usize;
    for (_col, val) in targets {
        seen += 1;
        let lower_val = if !val.is_error() {
            Value::string(
                val.to_expanded_string("", filter_config).to_lowercase(),
                Span::test_data(),
            )
        } else {
            (*val).clone()
        };
        if self.term_contains_value(term, &lower_val, span) {
            matched = true;
            break;
        }
        let _ = seen;
    }
    matched
}

fn highlight_record_columns(
