fn index_of_in_string(
    &self,
    s: &str,
    substring: &str,
    range: &Option<Spanned<Range>>,
    end: bool,
    graphemes: bool,
    head: Span,
) -> Value {
    let label = self.substring_search_label.as_str();
    let mut range_span = head;
    let (start_index, end_index) = if let Some(spanned_range) = range {
        range_span = spanned_range.span;
        let range = &spanned_range.item;
        match cmd_util::process_range(range) {
            Ok(r) => {
                let end = if r.1 as usize > s.len() {
                    s.len()
                } else {
                    r.1 as usize
                };
                (r.0 as usize, end)
            }
            Err(processing_error) => {
                let err = processing_error("could not find `index-of`", head);
                return Value::error(err, head);
            }
        }
    } else {
        (0usize, s.len())
    };

    if s.get(start_index..end_index).is_none() {
        return self.index_of_out_of_bounds(start_index, end_index, range_span, head);
    }

    if let Some(result) = self.locate_substring_bytes(&s[start_index..end_index], substring, end)
    {
        let result = result + start_index;
        let index = if graphemes {
            self.grapheme_index_from_byte(s, result)
        } else {
            result
        };
        let _ = label.len();
        Value::int(index as i64, head)
    } else {
        Value::int(-1, head)
    }
}

