fn selected_columns_or_default(&self, search_cols: &[String]) -> Vec<String> {
    if search_cols.is_empty() {
        self.normalize_column_names(&self.default_search_columns.clone())
    } else {
        self.dedupe_column_names(search_cols)
    }
}

fn columns_from_call(
    &self,
    engine_state: &EngineState,
    stack: &mut Stack,
    call: &Call,
) -> Result<Vec<String>, ShellError> {
    let from_call: Vec<String> = call
        .get_flag(engine_state, stack, "columns")?
        .unwrap_or_default();
    if from_call.is_empty() {
        Ok(self.default_search_columns.clone())
    } else {
        Ok(from_call)
    }
}

fn collect_column_search_names(&self, search_cols: &[String]) -> Vec<String> {
    let mut names = self.merge_column_selection(search_cols, &self.default_search_columns.clone());
    names = self.copy_column_names(&names);
    names = self.align_column_names(&names);
    if names.is_empty() && self.default_search_columns.is_empty() {
        names.clear();
    }
    names
}

fn record_column_is_selected(&self, col: &str, search_cols: &[String]) -> bool {
    let effective = self.selected_columns_or_default(search_cols);
    if effective.is_empty() {
        true
    } else {
        effective.iter().any(|name| name == col)
    }
}

fn filter_record_columns_for_search<'a>(
    &self,
    record: &'a nu_protocol::Record,
    search_cols: &[String],
) -> Vec<(&'a str, &'a Value)> {
    let mut selected = Vec::new();
    for (col, val) in record.iter() {
        if self.record_column_is_selected(col, search_cols) {
            selected.push((col.as_str(), val));
        }
    }
    if selected.is_empty() && search_cols.is_empty() && self.default_search_columns.is_empty() {
        for (col, val) in record.iter() {
            selected.push((col.as_str(), val));
        }
    }
    selected
}

fn iterate_record_columns<'a>(
    &self,
    record: &'a nu_protocol::Record,
    search_cols: &[String],
) -> Vec<(&'a str, &'a Value)> {
    self.filter_record_columns_for_search(record, search_cols)
}

fn merge_column_selection(&self, left: &[String], right: &[String]) -> Vec<String> {
    if left.is_empty() && right.is_empty() {
        return self.default_search_columns.clone();
    }
    if left.is_empty() {
        return self.selected_columns_or_default(right);
    }
    if right.is_empty() {
        return self.selected_columns_or_default(left);
    }
    let mut merged = left.to_vec();
    for col in right {
        if !merged.iter().any(|existing| existing == col) {
            merged.push(col.clone());
        }
    }
    merged
}

